```yaml
name: Claude Issue Triage

on:
  issues:
    types: [opened]

jobs:
  triage:
    runs-on: ubuntu-latest
    steps:
      - name: Call Claude API
        id: claude
        run: |
          response=$(curl -s -X POST https://api.anthropic.com/v1/messages \
            -H "x-api-key: ${{ secrets.ANTHROPIC_API_KEY }}" \
            -H "anthropic-version: 2023-06-01" \
            -H "content-type: application/json" \
            -d '{
              "model": "claude-3-5-sonnet-20240620",
              "max_tokens": 800,
              "messages": [
                {
                  "role": "user",
                  "content": "You are an issue triage assistant for the OB1 repository. The issue has the following details:\nTitle: ${{ github.event.issue.title }}\nBody: ${{ github.event.issue.body }}\nYour task:\n1. Classify the issue into one of the following categories: bug, recipe idea, schema idea, feature request, documentation, duplicate, or other.\n2. Check if the issue is a duplicate of an existing open issue. If so, provide the duplicate issue number.\n3. Assess if the issue scope fits the OB1 contribution guidelines. If it does not, suggest a better place or ask for clarification.\n4. Suggest appropriate labels to apply to the issue.\n5. Draft a welcoming comment that thanks the contributor, explains the triage result, and provides next steps.\nOutput in JSON format with keys: category, duplicate_issue, scope_fit, suggested_labels, comment."
                }
              ]
            }' \
          )
          echo "$response" > response.json
          content=$(jq -r '.content[0].text' response.json)
          echo "claude_json=$content" >> $GITHUB_OUTPUT
        env:
          ANTHROPIC_API_KEY: ${{ secrets.ANTHROPIC_API_KEY }}

      - name: Apply suggested labels
        uses: actions/github-script@v6
        with:
          script: |
            const output = JSON.parse(process.env.CLAUDE_JSON);
            if (output.suggested_labels && output.suggested_labels.length > 0) {
              await github.issues.addLabels({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                labels: output.suggested_labels
              });
            }
        env:
          CLAUDE_JSON: ${{ steps.claude.outputs.claude_json }}

      - name: Post welcoming comment
        uses: actions/github-script@v6
        with:
          script: |
            const output = JSON.parse(process.env.CLAUDE_JSON);
            if (output.comment) {
              await github.issues.createComment({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: context.issue.number,
                body: output.comment
              });
            }
        env:
          CLAUDE_JSON: ${{ steps.claude.outputs.claude_json }}
